const Valley=window.__GE.et(),audioStore=window.__GE.Y();
let introShown=false;
const valley=new Valley(document.getElementById('valley'),
  ()=>document.getElementById('loader').classList.add('gone'),
  ()=>{if(!introShown){introShown=true;document.getElementById('ui').classList.add('on')}});

const go=document.getElementById('go');
go.addEventListener('pointerenter',()=>valley.startHoverTransition());
go.addEventListener('pointerleave',()=>valley.stopHoverTransition());

const MUSIC_URL = "public/sound.mp3";
const ZH_SRT_URL = "public/zh.srt";
const VI_SRT_URL = "public/viet.srt";
document.addEventListener("DOMContentLoaded", () => {
  const soundBtn = document.getElementById("sound");
  const audio = document.getElementById("bg-music");
  const volumeSlider = document.getElementById("volume-slider");
  const lyricBox = document.getElementById("lyric-box");
  if (audio) { audio.loop = true; audio.src = MUSIC_URL; audio.onerror = () => console.error("Không nạp được nhạc:", MUSIC_URL); } 

  const updateLyricVisibility = () => {
    if (!lyricBox || !audio) return;
    if (audio.paused || audio.volume === 0) {
      lyricBox.classList.add("is-hidden");
    } else {
      lyricBox.classList.remove("is-hidden");
    }
  };

  if (audio) {
    audio.addEventListener("play", updateLyricVisibility);
    audio.addEventListener("pause", updateLyricVisibility);
    audio.addEventListener("volumechange", updateLyricVisibility);
  }

  let lastVolume = audio && audio.volume > 0 ? audio.volume : 1;

  if (volumeSlider && audio) {
    volumeSlider.value = String(audio.volume);
    volumeSlider.addEventListener("input", () => {
      const vol = parseFloat(volumeSlider.value);
      audio.volume = vol;
      if (vol > 0) {
        lastVolume = vol;
        if (audio.paused) {
          audio.play();
          removeUnlockListeners();
        }
      }
      if (soundBtn) {
        soundBtn.setAttribute("aria-pressed", !audio.paused && vol > 0 ? "true" : "false");
      }
      updateLyricVisibility();
    });
  }

  
  const startAudio = () => {
    if (!audio) return;
    
    audio.play().then(() => {
      
      if (soundBtn) soundBtn.setAttribute("aria-pressed", "true");
      removeUnlockListeners();
    }).catch(() => {
      
      if (soundBtn) soundBtn.setAttribute("aria-pressed", "false");
    });
  };

  
  const removeUnlockListeners = () => {
    ["click", "touchstart", "keydown", "wheel"].forEach(evt => {
      document.removeEventListener(evt, startAudio);
    });
  };

  
  startAudio();

  
  ["click", "touchstart", "keydown", "wheel"].forEach(evt => {
    document.addEventListener(evt, startAudio, { once: true });
  });

  
  if (soundBtn && audio) {
    soundBtn.addEventListener("click", (e) => {
      e.stopPropagation(); 
      if (audio.paused) {
        if (audio.volume === 0) {
          audio.volume = lastVolume > 0 ? lastVolume : 1;
        }
        if (volumeSlider) volumeSlider.value = String(audio.volume);
        audio.play();
        soundBtn.setAttribute("aria-pressed", "true");
      } else {
        if (audio.volume > 0) lastVolume = audio.volume;
        audio.pause();
        if (volumeSlider) volumeSlider.value = "0";
        soundBtn.setAttribute("aria-pressed", "false");
      }
      removeUnlockListeners();
    });
  }
});
const colZh = document.getElementById("col-zh");
  const colVi = document.getElementById("col-vi");
  const audioEl = document.getElementById("bg-music");

  let lyricsData = [];
  let currentIndex = -1;
  let revealTimers = [];

  
  function parseSrtTime(timeStr) {
    const [hms, ms] = timeStr.trim().replace(".", ",").split(",");
    const [h, m, s] = hms.split(":").map(Number);
    return h * 3600 + m * 60 + s + Number(ms || 0) / 1000;
  }

  
  async function fetchAndParseSrt(url) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Không tải được file: ${url}`);
    const text = await res.text();
    const blocks = text.trim().split(/\r?\n\r?\n+/);

    return blocks.map(block => {
      const lines = block.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
      const timeLineIndex = lines.findIndex(l => l.includes("-->"));
      if (timeLineIndex === -1) return null;

      const [startStr, endStr] = lines[timeLineIndex].split("-->");
      return {
        start: parseSrtTime(startStr),
        end: parseSrtTime(endStr),
        text: lines.slice(timeLineIndex + 1).join(" ")
      };
    }).filter(Boolean);
  }

  
  async function loadBilingualLyrics(zhUrl = ZH_SRT_URL, viUrl = VI_SRT_URL) {
    try {
      const [zhList, viList] = await Promise.all([
        fetchAndParseSrt(zhUrl),
        fetchAndParseSrt(viUrl)
      ]);

      const maxLen = Math.max(zhList.length, viList.length);
      lyricsData = [];

      for (let i = 0; i < maxLen; i++) {
        const zhItem = zhList[i];
        const viItem = viList[i];
        const base = zhItem || viItem;

        lyricsData.push({
          start: base.start,
          end: base.end,
          zh: zhItem ? zhItem.text : "",
          vi: viItem ? viItem.text : ""
        });
      }
    } catch (err) {
      console.error("Lỗi nạp phụ đề SRT:", err);
    }
  }

  function renderLyricPair(index) {
    revealTimers.forEach(timer => clearTimeout(timer));
    revealTimers = [];

    colZh.innerHTML = "";
    colVi.innerHTML = "";

    if (index < 0 || index >= lyricsData.length) return;

    const item = lyricsData[index];
    
    const durationMs = Math.max(800, (item.end - item.start) * 1000 * 0.65);

    
    const zhChars = item.zh.replace(/\s+/g, "").split("");
    const zhStep = Math.min(95, durationMs / Math.max(1, zhChars.length));
    zhChars.forEach((char, i) => {
      const span = document.createElement("span");
      span.className = "lyric-char-zh";
      span.textContent = char;
      colZh.appendChild(span);

      const t = setTimeout(() => span.classList.add("show"), i * zhStep);
      revealTimers.push(t);
    });

    
    const viWords = item.vi.trim().split(/\s+/).filter(Boolean);
    const viStep = Math.min(90, durationMs / Math.max(1, viWords.length));
    viWords.forEach((word, i) => {
      const span = document.createElement("span");
      span.className = "lyric-word-vi";
      span.textContent = word;
      colVi.appendChild(span);

      const t = setTimeout(() => span.classList.add("show"), i * viStep);
      revealTimers.push(t);
    });
  }

  
  loadBilingualLyrics(ZH_SRT_URL, VI_SRT_URL);

  if (audioEl) {
    audioEl.addEventListener("timeupdate", () => {
      const currentTime = audioEl.currentTime;
      let activeIndex = -1;

      for (let i = 0; i < lyricsData.length; i++) {
        if (currentTime >= lyricsData[i].start && currentTime <= lyricsData[i].end) {
          activeIndex = i;
          break;
        }
      }

      if (activeIndex !== currentIndex) {
        currentIndex = activeIndex;
        renderLyricPair(currentIndex);
      }
    });
  }